  id Int @id
  clienteId Int @map("cliente_id")
  total Decimal?
  itemPedidos ItemPedido[]
}

model Cliente {
  id Int @id
  nome String
}

model ItemPedido {
  pedidoId Int @map("pedido_id")
  produtoCodigo BigInt @map("produto_codigo")
  quantidade Int
  preco Decimal?
  pedido Pedido @relation(fields: [pedidoId], references: [id])

  @@id([pedidoId, produtoCodigo])
  @@unique([pedidoId, quantidade])
  @@map("item_pedido")
